/* Server-cached simulations: the same result for every visitor. */
let playoffLoadGeneration=0;
async function renderPlayoffs(){
 const generation=++playoffLoadGeneration;
 app.innerHTML=`<div class="page z-page">${pageHero('2026 SEASON','The playoff picture.','Twelve teams. One finish line.')}<section class="section"><div class="wrap" id="playoffContent"><div class="playoff-loader" role="status">Running the remaining season through 20,000 possibilities…</div></div></section></div>`;
 try{
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);let response;
  try{response=await fetch('/api/playoffs',{signal:controller.signal,cache:'no-store'});}finally{clearTimeout(timer);}
  const model=await response.json();if(!response.ok)throw new Error(model.error||'The playoff model is temporarily unavailable.');
  if(currentPage!=='playoffs'||generation!==playoffLoadGeneration)return;
  if(!Array.isArray(model.teams)||!model.teams.length)throw new Error('No validated simulation results were returned.');
  const root=document.getElementById('playoffContent'),percent=n=>n===100?'100%':n===0?'0%':n>=99.95?'>99.9%':n<.05?'<0.1%':n.toFixed(1)+'%';
  root.innerHTML=`<div class="playoff-meta"><strong>${model.spots} playoff spots</strong><span>Records through Week ${model.through}</span><span>${fmt(model.iterations,0)} simulations</span>${model.stale?'<span>Using the last saved forecast</span>':''}</div><ol class="playoff-list" aria-label="Teams ordered by playoff probability">${model.teams.map((t,i)=>`<li class="playoff-row ${i===model.spots-1?'cut-line':''}"><strong class="z-rank">${i+1}</strong>${photo(t.avatar?'https://sleepercdn.com/avatars/thumbs/'+encodeURIComponent(t.avatar):'',t.manager)}<div class="playoff-team"><h3>${e(t.team)}</h3><small>${e(t.manager)} · ${weekRecord(t.record)}</small></div><div class="playoff-bar"><div class="odds-track" role="meter" aria-label="${e(t.team)} playoff probability" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${t.odds.toFixed(2)}"><div class="odds-fill" style="width:${Math.max(0,Math.min(100,t.odds))}%"></div></div><div class="odds-caption">${t.odds>=80?'In the driver’s seat':t.odds>=55?'Holding an edge':t.odds>=35?'In the mix':t.odds>=15?'Work to do':'Long road ahead'}</div></div><strong class="playoff-chance">${percent(t.odds)}</strong></li>`).join('')}</ol><details class="method-disclosure"><summary>How the forecast works</summary><p>Every simulation begins with finalized Weeks 1–${model.through}: wins, losses, ties, points for and points against stay fixed. The real Sleeper opponent pairings are simulated from Week ${model.through+1} through Week ${model.end}. An unfinished week is simulated in full; in-progress points are not locked into this forecast.</p><p>CBS Sports expert ROS counting-stat projections are re-scored under this league’s scoring settings and divided by projected games played. For each future week, we select the highest-projected legal lineup from each current roster, using each player once. Confirmed NFL byes force bench replacements. Current unavailable players miss the earliest scheduled games implied by the expert games-played forecast (at least one); this is a recovery assumption, not a confirmed return date. If rearranging the roster still leaves a gap, the model adds the highest-projected eligible free agents needed to complete it. These are temporary weekly streaming assumptions, not actual transactions; full rosters are not upgraded. Free agents exclude every team’s roster, IR and taxi squad. Same-week pickups are exclusive, awarded in current waiver-position order (otherwise worst current record/PF first); availability resets next week. Future trades are not forecast.</p><p>Scores vary using position-based player standard deviations: QB 35%, RB 50%, WR 60%, TE 65%, K 45%, DEF 75% of the expected score, with a 3-point minimum (5 for defense). Same-NFL-team players have 15% positive correlation. These are modeling assumptions, not a calibrated claim of predictive accuracy. Team scores are sampled from a normal distribution and rounded to two decimals; ties remain ties.</p><p>Seeding follows Sleeper: overall winning percentage (ties count as half a win), total points for, then higher points against, then a random coin toss. ${model.divisions>1?'Division winners receive the leading seeds before remaining qualifiers.':'There are no division-winner reservations.'} ${model.median?'The league’s extra game against the median is included.':''} Commissioner overrides cannot be inferred from the API.</p><p>${model.expertSlots} starter-week slots use CBS ROS; ${model.fallbackSlots} use fallback projections or replacement estimates. ${model.waiverSlots||0} slots are modeled waiver pickups. ${model.recentProjectionSlots||0} use the average of up to three recent positive Sleeper projections when a future projection is missing or zero, with current availability and future byes still checked. ${model.estimatedReplacementSlots||0} use a generic replacement-level estimate because no eligible free agent had a positive forecast; these are explicitly estimates, not named expert-projected pickups. Emergency estimates are QB 12, RB 5, WR 6, TE 4, K 6 and DEF 5 points. No starting slot is left empty or projected at zero. Missing finalized results or opponent schedules can still stop publication. ${model.unsupportedScoring?.length?`The ROS stat source does not project these scoring fields: ${e(model.unsupportedScoring.join(', '))}. They are omitted from ROS scoring, so the forecast is approximate.`:''}</p><p>Expert data checked ${e(new Date(model.expertAsOf).toLocaleString())}. Forecast generated ${e(new Date(model.generatedAt).toLocaleString())}. Cached for five minutes; expert forecasts refresh every six hours. With 20,000 simulations, the largest Monte Carlo sampling error is about ±0.7 percentage points at 95% confidence; forecast uncertainty is larger.</p><p>${(model.expertLinks||[]).map((url,i)=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">CBS ${['QB','RB','WR','TE'][i]} ROS projections</a>`).join(' · ')} · <a href="https://support.sleeper.com/en/articles/2203518-how-do-playoff-teams-get-determined" target="_blank" rel="noopener noreferrer">Sleeper seeding rules</a></p></details>`;
  wireImageFallback(root);
 }catch(error){if(currentPage!=='playoffs'||generation!==playoffLoadGeneration)return;document.getElementById('playoffContent').innerHTML=`<div class="live-error"><strong>The playoff forecast could not be refreshed.</strong><p>${e(error.name==='AbortError'?'The initial forecast took too long. Try again in a moment.':error.message)}</p><button class="dd-action" id="retryPlayoffs">Retry forecast</button></div>`;document.getElementById('retryPlayoffs').onclick=renderPlayoffs;}
}
